      SUBROUTINE ROTAT3(NM)CC     ROTATION OF THIRD-ORDER TRANSFER MATRIX ELEMENTCC ----------------------------------------------------------------------      INCLUDE 'ELM20.CIN'      INCLUDE 'U.CIN'      INCLUDE 'US.CIN'CC     LOCAL VARIABLESC      REAL            USAV(6,6,6)C --------------------------------------------------------------------CC     IDENTIFY MATRIX TO BE ROTATEDC      IF (NM .EQ. 0) THEN        DO 20 JKLM = 1, 280   20   USL(JKLM) = UL(JKLM)      ELSE        DO 60 JKLM = 1, 280   60   USL(JKLM) = UVL(JKLM)      ENDIFCC     ROTATE AT ENTRANCEC  100 DO 180 I = 1, 5      JKL = 0      DO 155 L = 1, 6      DO 155 K = 1, L      DO 155 J = 1, K      JKL = JKL + 1      USIJKL = US(I,JKL)      USAV(J,K,L) = USIJKL      USAV(J,L,K) = USIJKL      USAV(K,J,L) = USIJKL      USAV(K,L,J) = USIJKL      USAV(L,J,K) = USIJKL  155 USAV(L,K,J) = USIJKLC      DO 160 L = 1, 6      DO 160 K = 1, 6      US1 = USAV(1,K,L)      USAV(1,K,L) = US1*CSR - USAV(3,K,L)*SNR      USAV(3,K,L) = US1*SNR + USAV(3,K,L)*CSR      US2 = USAV(2,K,L)      USAV(2,K,L) = US2*CSR - USAV(4,K,L)*SNR      USAV(4,K,L) = US2*SNR + USAV(4,K,L)*CSR  160 CONTINUEC      DO 165 L = 1, 6      DO 165 J = 1, 6      US1 = USAV(J,1,L)      USAV(J,1,L) = US1*CSR - USAV(J,3,L)*SNR      USAV(J,3,L) = US1*SNR + USAV(J,3,L)*CSR      US2 = USAV(J,2,L)      USAV(J,2,L) = US2*CSR - USAV(J,4,L)*SNR      USAV(J,4,L) = US2*SNR + USAV(J,4,L)*CSR  165 CONTINUEC      DO 170 K = 1, 6      DO 170 J = 1, 6      US1 = USAV(J,K,1)      USAV(J,K,1) = US1*CSR - USAV(J,K,3)*SNR      USAV(J,K,3) = US1*SNR + USAV(J,K,3)*CSR      US2 = USAV(J,K,2)      USAV(J,K,2) = US2*CSR - USAV(J,K,4)*SNR      USAV(J,K,4) = US2*SNR + USAV(J,K,4)*CSR  170 CONTINUEC      JKL = 0      DO 175 L = 1, 6      DO 175 K = 1, L      DO 175 J = 1, K      JKL = JKL + 1      USIJKL = USAV(J,K,L)  175 US(I,JKL) = USIJKL  180 CONTINUECC     ROTATE AT EXITC  200 JKL = 0      DO 245 L = 1, 6      DO 245 K = 1, L      DO 245 J = 1, K      JKL = JKL + 1      UT(1,JKL) = US(1,JKL)*CSR - US(3,JKL)*SNR      UT(3,JKL) = US(1,JKL)*SNR + US(3,JKL)*CSR      UT(2,JKL) = US(2,JKL)*CSR - US(4,JKL)*SNR      UT(4,JKL) = US(2,JKL)*SNR + US(4,JKL)*CSR  245 CONTINUE      DO 250 I = 1, 4      DO 250 JKL = 1, 56  250 US(I,JKL) = UT(I,JKL)CC     REPLACE ROTATED MATRIXC  400 IF (NM .EQ. 0) THEN        DO 420 JKLM = 1, 280  420   UL(JKLM) = USL(JKLM)      ELSE        DO 470 JKLM = 1, 280  470   UVL(JKLM) = USL(JKLM)      ENDIFC  500 CONTINUE      RETURN      END